'use client';

import { useRef, type CSSProperties, type ReactNode } from 'react';
import { usePlayback } from './use-playback';
import './orbiting-marks.css';

export interface OrbitingMarksProps {
  /** The content in the middle. It never moves. */
  children: ReactNode;
  /** Marks on the inner and outer orbit. */
  inner?: number;
  outer?: number;
  /** 1 is normal speed; 2 is twice as fast. */
  speed?: number;
  paused?: boolean;
  className?: string;
}

/**
 * Small decorative marks circle a still centerpiece on two orbits, in
 * opposite directions. They are hidden from assistive technology, stop when
 * paused, off screen or in a hidden tab, and stay still with reduced motion.
 */
export function OrbitingMarks({
  children,
  inner = 3,
  outer = 5,
  speed = 1,
  paused = false,
  className = '',
}: OrbitingMarksProps) {
  const root = useRef<HTMLDivElement>(null);
  const playing = usePlayback(root, paused);
  const ring = (count: number, which: 'inner' | 'outer') => (
    <div
      className={`mg-orbit__ring mg-orbit__ring--${which}`}
      aria-hidden='true'
    >
      {Array.from({ length: count }, (_, i) => (
        <span
          key={i}
          className='mg-orbit__arm'
          style={{ '--mg-angle': `${(360 / count) * i}deg` } as CSSProperties}
        >
          <span className='mg-orbit__mark' />
        </span>
      ))}
    </div>
  );
  return (
    <div
      ref={root}
      className={`mg-orbit ${className}`}
      data-playing={playing}
      style={{ '--mg-speed': speed } as CSSProperties}
    >
      {ring(outer, 'outer')}
      {ring(inner, 'inner')}
      <div className='mg-orbit__center'>{children}</div>
    </div>
  );
}

.mg-orbit {
  --mg-size: 220px;
  position: relative;
  display: grid;
  place-items: center;
  width: var(--mg-size);
  height: var(--mg-size);
  color: var(--mg-ink, #0c1738);
}

.mg-orbit__ring {
  position: absolute;
  border: 1px dashed #c3cdec;
  border-radius: 50%;
  animation: mg-orbit-spin calc(16s / var(--mg-speed)) linear infinite;
  animation-play-state: paused;
}

.mg-orbit__ring--outer {
  inset: 0;
}

.mg-orbit__ring--inner {
  inset: 42px;
  animation-direction: reverse;
  animation-duration: calc(10s / var(--mg-speed));
}

.mg-orbit[data-playing='true'] .mg-orbit__ring {
  animation-play-state: running;
}

/* Each arm points from the center to the ring at its angle. */
.mg-orbit__arm {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 50%;
  height: 0;
  transform: rotate(var(--mg-angle));
  transform-origin: left center;
}

.mg-orbit__mark {
  position: absolute;
  top: -6px;
  right: -6px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--mg-accent, #164cff);
}

.mg-orbit__ring--inner .mg-orbit__mark {
  border-radius: 2px;
  background: var(--mg-green, #b6ff3b);
  box-shadow: 0 0 0 1px var(--mg-ink, #0c1738);
}

.mg-orbit__center {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 92px;
  height: 92px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 10px 22px -12px rgba(12, 23, 56, 0.5);
  text-align: center;
}

@keyframes mg-orbit-spin {
  to {
    transform: rotate(1turn);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-orbit__ring {
    animation: none;
  }
}

'use client';

import { useEffect, useState, type RefObject } from 'react';

/**
 * Whether a continuous effect should run: its element is on screen, the
 * browser tab is visible and the caller has not paused it. Loops should stop
 * (or set `animation-play-state: paused`) whenever this returns false.
 */
export function usePlayback(
  ref: RefObject<Element | null>,
  paused = false
): boolean {
  const [onScreen, setOnScreen] = useState(false);
  const [pageVisible, setPageVisible] = useState(true);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === 'undefined') {
      setOnScreen(true);
      return;
    }
    const observer = new IntersectionObserver(([entry]) =>
      setOnScreen(entry.isIntersecting)
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  useEffect(() => {
    const update = () => setPageVisible(document.visibilityState !== 'hidden');
    update();
    document.addEventListener('visibilitychange', update);
    return () => document.removeEventListener('visibilitychange', update);
  }, []);

  return onScreen && pageVisible && !paused;
}
